"""Manual photo tracing, not metrology. Retains pixel observations and source IDs.
No assumed symmetry, no inferred screw/slot dimensions. NumPy is used only to
register the second view to the primary view using four common hole centres.
"""
import json, math
from pathlib import Path
import numpy as np
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'assembly/sources/chassis-photo-trace.json'
OBS=json.loads((ROOT/'assembly/references/chassis-observations.json').read_text())
# Four visible small round holes. Source image 02 -> source image 03.
a=np.array([[221,345],[1399,362],[209,950],[1400,959]],float)
b=np.array([[210,355],[1413,348],[210,964],[1429,956]],float)
A=[];rhs=[]
for (x,y),(u,v) in zip(a,b):
 A.extend([[x,y,1,0,0,0,-u*x,-u*y],[0,0,0,x,y,1,-v*x,-v*y]]);rhs.extend([u,v])
H=np.append(np.linalg.solve(A,rhs),1).reshape(3,3)
def register(p,source):
 if source==3:return list(p)
 q=H@np.array([*p,1]);return list(q[:2]/q[2])
def mm(p):
 # Explicit envelope normalization. Does NOT claim camera/lens calibration.
 u,v=p;u0,v0,u1,v1=BOUNDS;return [round((v-v0)/(v1-v0)*150-75,2),round(127.5-(u-u0)/(u1-u0)*255,2)]
features=[]
def polygon(id,points,source=3,kind='slot'):
 pix=[register(p,source) for p in points]
 features.append(dict(id=id,kind=kind,source_image=source,observed_pixels=points,polygon_xy=[mm(p) for p in pix],status='PHOTO_ESTIMATE_UNVERIFIED'))
def ellipse(id,c,r,source=3):
 pts=[[c[0]+r[0]*math.cos(i*math.tau/24),c[1]+r[1]*math.sin(i*math.tau/24)] for i in range(24)]
 polygon(id,pts,source,'round');features[-1]['observed_centre_px']=c;features[-1]['observed_radii_px']=r
# Outer contour: observed left and centre from 03; right end visible in 02.
left=[(244,207),(213,214),(178,234),(145,267),(113,309),(88,357),(68,413),(51,476),(40,540),(34,605),(34,673),(38,748),(48,817),(64,884),(85,947),(113,1006),(143,1052),(178,1087),(211,1108),(244,1117)]
bottom=[(244,965),(548,965),(551,958),(625,958),(628,967),(706,967),(707,1105),(712,1115),(917,1115),(928,1106),(928,961),(1003,961),(1005,952),(1080,953),(1080,961),(1202,961)]
right2=[(1362,954),(1365,1103),(1399,1094),(1431,1074),(1462,1043),(1490,1005),(1515,957),(1536,905),(1553,846),(1565,785),(1571,720),(1574,655),(1570,589),(1560,525),(1546,465),(1527,406),(1502,352),(1474,304),(1444,265),(1412,236),(1370,217),(1361,357),(1075,357),(1073,365),(1000,365),(999,357)]
right=[register(p,2) for p in right2]
