outline_px=left+bottom+right+top
BOUNDS=[min(p[0] for p in outline_px),min(p[1] for p in outline_px),max(p[0] for p in outline_px),max(p[1] for p in outline_px)]
# Circular apertures, each separately observed; large circles are not forced equal.
for id,c,r in [('C01',(214,659),(58,58)),('H01',(149,297),(9,10)),('H02',(105,371),(9,10)),('H03',(210,355),(10,11)),('H04',(298,400),(10,11)),('H05',(480,398),(10,11)),('H06',(588,398),(10,11)),('H07',(60,616),(9,10)),('H08',(59,702),(9,10)),('H09',(457,655),(10,11)),('H10',(657,654),(10,11)),('H11',(834,653),(10,11)),('H12',(1019,533),(9,10)),('H13',(1022,702),(9,10)),('H14',(1168,651),(10,11)),('H15',(770,232),(10,11)),('H16',(854,231),(10,11)),('H17',(811,313),(10,11)),('H18',(891,381),(10,11)),('H19',(895,931),(10,11)),('H20',(817,1002),(10,11)),('H21',(774,1087),(10,11)),('H22',(861,1086),(10,11)),('H23',(588,918),(10,11)),('H24',(480,919),(10,11)),('H25',(297,921),(10,11)),('H26',(210,963),(10,11)),('H27',(104,947),(9,10)),('H28',(146,1027),(9,10))]:ellipse(id,c,r)
for id,c,r in [('C02',(1394,659),(55,55)),('H29',(1459,306),(8,10)),('H30',(1500,380),(8,10)),('H31',(1399,362),(10,10)),('H32',(1317,390),(10,10)),('H33',(1327,512),(9,10)),('H34',(1315,798),(9,10)),('H35',(1316,926),(10,10)),('H36',(1401,960),(10,10)),('H37',(1500,941),(8,10)),('H38',(1461,1015),(8,10)),('H39',(1551,617),(8,10)),('H40',(1552,701),(8,10))]:ellipse(id,c,r,2)
# Straight rectangular apertures, traced corner by corner (not generated by mirroring).
rects=[[(218,447),(268,446),(268,473),(217,475)],[(219,495),(267,494),(267,522),(218,522)],[(219,545),(267,544),(267,573),(218,573)],[(218,746),(267,746),(267,775),(218,775)],[(218,797),(268,796),(268,824),(218,825)],[(218,848),(269,847),(269,875),(218,875)],[(553,478),(626,478),(626,498),(553,498)],[(551,817),(626,818),(626,837),(551,837)],[(675,550),(726,550),(726,578),(675,579)],[(675,734),(727,734),(727,762),(675,762)],[(768,347),(856,348),(856,375),(768,374)],[(773,939),(861,939),(861,966),(773,965)],[(1002,475),(1075,474),(1075,495),(1002,495)],[(1006,814),(1079,814),(1079,834),(1006,834)]]
