polygon('X04',[(1139,744),(1170,744),(1170,753),(1181,765),(1216,769),(1216,804),(1191,804),(1180,817),(1179,828),(1137,828),(1135,815),(1122,806),(1097,804),(1097,770),(1123,769),(1138,755)],2)
