polygon('S01',[(100,463),(107,461),(114,466),(115,475),(113,846),(110,857),(103,861),(97,857),(94,849),(96,474)])
polygon('S02',[(203,267),(210,265),(216,270),(216,278),(123,431),(117,438),(109,438),(104,433),(105,426)])
