polygon('S06',[(1488,878),(1496,876),(1502,881),(1501,891),(1411,1041),(1403,1048),(1396,1048),(1393,1041),(1395,1033)],2)
model=dict(schema=1,status='PHOTO_TRACE_NOT_MEASURED_CAD',units='mm',date='2026-10-15',envelope_basis='255 x 150 mm reported by user on 2026-10-14; normalized photo envelope, not dimensions independently read from ruler',length_mm=255,width_mm=150,thickness_mm=OBS['plate_thickness_mm'],clear_gap_mm=OBS['plate_gap_mm'],vertical_measurement_source=OBS.get('vertical_measurement_source'),axes='x across width, y along length toward end A (left end of photographs 02-05); no robot front assigned',normalization={'primary_image':3,'pixel_bounds':BOUNDS,'method':'axis-aligned affine envelope normalization; lens/perspective residuals uncalibrated'},registration={'source':2,'target':3,'source_points':a.tolist(),'target_points':b.tolist(),'homography':H.tolist()},outline={'source_images':[3,2],'registered_pixels':outline_px,'polygon_xy':[mm(p) for p in outline_px]},features=features,excluded_from_claims=['Exact hole diameters and centres','Manufacturing tolerances','Screw size and length','Motor and electronics mounting assignments'],sources={str(i):f'../references/2026-10-15/{n}.png' for i,n in enumerate(['01-length','02-width-centre','03-width-end','04-length-upper','05-length-middle','06-slot-closeup','07-slot-closeup'],1)})
OUT.write_text(json.dumps(model,ensure_ascii=False,indent=2)+'\n')
print(f'{len(features)} independently traced openings; photo estimates only -> {OUT}')
